import{_ as u,a0 as s,w as o,s as p,ao as g,I as l,x as i,a1 as e,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"修補 Linux 系統 glibc 嚴重漏洞 | LCTT x X-CMD","titleTemplate":false,"description":"修補 Linux 系統 glibc 嚴重漏洞 | LCTT (201606) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修補 Linux 系統 glibc 嚴重漏洞 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修補 Linux 系統 glibc 嚴重漏洞 | LCTT (201606) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201606/20160218 Linux Systems Patched for Critical glibc Flaw","title":"修補 Linux 系統 glibc 嚴重漏洞","tag":"201606","desc":""},"relativePath":"201606/20160218 Linux Systems Patched for Critical glibc Flaw.md","filePath":"[post].md"}'),b={name:"201606/20160218 Linux Systems Patched for Critical glibc Flaw.md"};function a(d,t,x,m,f,L){const n=s("Link");return o(),p("div",null,[t[16]||(t[16]=g('<h1 id="修補-linux-系統-glibc-嚴重漏洞" tabindex="-1">修補 Linux 系統 glibc 嚴重漏洞 <a class="header-anchor" href="#修補-linux-系統-glibc-嚴重漏洞" aria-label="Permalink to “修補 Linux 系統 glibc 嚴重漏洞”">​</a></h1><p><strong>谷歌披露的一個嚴重漏洞影響到了主流的 Linux 發行版。glibc 的漏洞可能導致遠程代碼執行。</strong></p><p>編者按：這個消息並不是一個新聞，基於技術的原因，我們還是分享給大家。</p><p>Linux 用户都在競相給一個可以使系統暴露在遠程代碼執行風險中的核心 glibc 開放源碼庫的嚴重漏洞打補丁。這個 glibc 的漏洞編號被確定為 CVE-2015-7547，題為“getaddrinfo 基於堆棧的緩衝區溢出”。</p><p>glibc，或 GNU C 庫，是一個開放源碼的 C 和 C++ 編程語言庫的實現，是每一個主流 Linux 發行版的一部分。谷歌工程師們在他們試圖連接到某個主機系統時發生了一個段錯誤導致連接崩潰，偶然發現了 CVE-2015-7547 問題。進一步的研究表明， glibc 有缺陷而且該崩潰可能實現任意遠程代碼執行的條件。</p><p>谷歌在一篇Blog文章中寫道, “當 getaddrinfo() 庫函數被使用時，glibc 的 DNS 客户端解析器易受基於堆棧緩衝區溢出的攻擊，使用該功能的軟件可能通過攻擊者控制的域名、攻擊者控制的 DNS [域名系統] 服務器，或通過中間人攻擊方式（MITM）進行破壞。”</p><p>其實利用 CVE-2015-7547 問題並不簡單，但它是可能的。為了證明這個問題能被利用，谷歌發佈了論證一個終端用户或系統是否易受攻擊的概念驗證（POC）代碼到 GitHub 上。</p><p>GitHub 上的 POC 網頁説“服務器代碼會觸發漏洞，因此會使客户端代碼崩潰”。</p><p>Duo Security 公司的高級安全研究員 Mark Loveless 解釋説 CVE-2015-7547 的主要風險在於依賴於 DNS 響應的基於 Linux 客户端的應用程序。</p><p>Loveless 告訴 eWEEK “需要一些特定的條件，所以不是每個應用程序都會受到影響，但似乎一些命令列工具，包括流行的 SSH[安全 Shell] 客户端都可能觸發該漏洞，我們認為這是嚴重的，主要是因為對 Linux 系統存在的風險，但也因為潛在的其他問題。”</p><p>其他問題可能包括一種通過電子郵件觸發調用易受攻擊的 glibc 庫 getaddrinfo() 攻擊的風險。另外值得注意的是，該漏洞被發現之前已存在於代碼之中多年。</p>',11)),l("p",null,[t[1]||(t[1]=i("谷歌的工程師不是第一或唯一發現這個 glibc 安全風險的團體。這個問題於 2015 年 7 月 13 日首先被報告給了 glibc 的 bug",-1)),e(n,{href:"https://sourceware.org/bugzilla/show_bug.cgi?id=1866"},{default:r(()=>[...t[0]||(t[0]=[i("跟蹤系統",-1)])]),_:1}),t[2]||(t[2]=i("。該缺陷的根源可以更進一步追溯到在 2008 五月發佈的 glibc 2.9 的代碼提交時首次引入缺陷。",-1))]),t[17]||(t[17]=l("p",null,"Linux 廠商紅帽也獨立找到了 glibc 中的這個 bug，而且是在 2016 年 1 月 6 日，谷歌和紅帽開發人員證實，他們作為最初與上游 glibc 的維護者私下討論的部分人員，已經獨立在為同一個漏洞工作。",-1)),t[18]||(t[18]=l("p",null,"紅帽產品安全首席軟件工程師 Florian Weimer 告訴 eWEEK “一旦確認了兩個團隊都在為同一個漏洞工作，我們會合作進行可能的修復，緩解措施和迴歸測試，我們還會共同努力，使測試覆蓋儘可能廣，捕捉代碼中的任何相關問題，以幫助避免今後更多問題。”",-1)),t[19]||(t[19]=l("p",null,"由於缺陷不明顯或不易立即顯現，我們花了幾年時間才發現 glibc 代碼有一個安全問題。",-1)),t[20]||(t[20]=l("p",null,"Weimer 説“要診斷一個網絡組件的漏洞，如 DNS 解析器，當遇到問題時通常要看抓到的數據包的蹤跡，在這種情況下這樣的抓包不適用，所以需要一些實驗來重現觸發這個 bug 的確切場景。”",-1)),t[21]||(t[21]=l("p",null,"Weimer 補充説，一旦可以抓取數據包，就會投入大量精力到驗證修復程序中，最終完成迴歸測試套件一系列的改進，有助於上游 glibc 項目。",-1)),t[22]||(t[22]=l("p",null,"在許多情況下，安全增強式 Linux (SELinux) 的強制訪問安全控制可以減少潛在漏洞風險，但是這個 glibc 的新問題例外。",-1)),t[23]||(t[23]=l("p",null,"Weimer 説“由於攻擊者提供的任意代碼的執行，會對很多重要系統功能帶來風險。一個合適的 SELinux 策略可以遏制一些攻擊者可能會做的損害，並限制他們訪問系統，但是 DNS 被許多應用程序和系統組件使用，所以 SELinux 策略只提供了針對此問題有限的遏制。”",-1)),t[24]||(t[24]=l("p",null,"在揭露漏洞的今天，現在有一個可用的補丁來減少 CVE-2015-7547 的潛在風險。",-1)),t[25]||(t[25]=l("hr",null,null,-1)),l("p",null,[t[4]||(t[4]=i("via: ",-1)),e(n,{href:"http://www.eweek.com/security/linux-systems-patched-for-critical-glibc-flaw.html"},{default:r(()=>[...t[3]||(t[3]=[i("http://www.eweek.com/security/linux-systems-patched-for-critical-glibc-flaw.html",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=i("作者：",-1)),e(n,{href:"https://twitter.com/TechJournalist"},{default:r(()=>[...t[5]||(t[5]=[i("Michael Kerner",-1)])]),_:1}),t[9]||(t[9]=i(" 譯者：",-1)),e(n,{href:"https://github.com/robot527"},{default:r(()=>[...t[6]||(t[6]=[i("robot527",-1)])]),_:1}),t[10]||(t[10]=i(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[i("LCTT",-1)])]),_:1}),t[14]||(t[14]=i(" 原創翻譯，",-1)),e(n,{href:"https://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[i("Linux 中國",-1)])]),_:1}),t[15]||(t[15]=i(" 榮譽推出",-1))])])}const S=u(b,[["render",a]]);export{w as __pageData,S as default};
